#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

// Dummy handler function
void sig_handler(int signum) {
    printf("\n[Handler] Signal %d delivered successfully.\n", signum);
}

int main() {
    sigset_t blocked_set, pending_set, old_set;
    struct sigaction sa;
    int sig_to_test = SIGUSR1;

    // 1. Setup a basic signal handler for SIGUSR1
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(sig_to_test, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // 2. Define the set of signals to block (SIGUSR1)
    sigemptyset(&blocked_set);
    sigaddset(&blocked_set, sig_to_test);

    // 3. Block SIGUSR1 (saving the old mask for restoration)
    if (sigprocmask(SIG_BLOCK, &blocked_set, &old_set) == -1) {
        perror("sigprocmask SIG_BLOCK");
        return EXIT_FAILURE;
    }
    printf("Blocking SIGUSR1. PID: %d\n", getpid());

    // 4. Raise the signal while it is blocked
    printf("Raising SIGUSR1 (it should now be pending)...
");
    if (raise(sig_to_test) != 0) {
        perror("raise");
        sigprocmask(SIG_SETMASK, &old_set, NULL); // Cleanup
        return EXIT_FAILURE;
    }

    // 5. Check which signals are pending for this thread
    if (sigpending(&pending_set) == -1) {
        perror("sigpending");
        sigprocmask(SIG_SETMASK, &old_set, NULL); // Cleanup
        return EXIT_FAILURE;
    }

    // 6. Verify if SIGUSR1 is present in the pending set
    if (sigismember(&pending_set, sig_to_test)) {
        printf("Verification Success: SIGUSR1 is currently pending.\n");
    } else {
        printf("Verification Failure: SIGUSR1 is NOT pending.\n");
    }

    // 7. Restore the original signal mask, causing the pending signal to be delivered
    printf("Unblocking SIGUSR1 and restoring mask...\n");
    if (sigprocmask(SIG_SETMASK, &old_set, NULL) == -1) {
        perror("sigprocmask SIG_SETMASK");
        return EXIT_FAILURE;
    }

    printf("Main function resuming.\n");
    return EXIT_SUCCESS;
}
